// Pattern 1: Mutable entity with audit trail
export interface Workout {
  id: string
  user_id: string
  name: string
  exercises: Exercise[]
  created_at: Date
  updated_at: Date
  deleted_at?: Date
}

// Pattern 2: Domain enum (pgEnum source of truth in DB)
export type WorkoutType =
  | 'strength'
  | 'cardio'
  | 'flexibility'
  | 'sports'

// Pattern 3: Input vs stored (Zod validation separates them)
export interface CreateWorkoutInput {
  name: string
  exercises: CreateExerciseInput[]
}
// Stored version has id, timestamps, user_id added by DB layer

// Lambda handler (packages pattern from createAuthorizer)
export const handler: Handler = async (event) => {
  const userId = getUserId(event) // Validates, extracts, throws 401 if invalid

  if (!userId) {
    return error(401, 'Unauthorized')
  }

  // Safe to use userId for all subsequent queries
  // RLS policies provide additional row-level security
}

// Next.js API route
export async function GET(req: NextRequest) {
  const userId = requireUser(req) // Throws if no valid token

  // userId is now guaranteed to be a string
  const data = await getWorkouts(userId)
  return Response.json(data)
}

