// Prevents XSS and SQL-like patterns
export function sanitizeSearchQuery(input: string): string {
  return input
    .replace(/[<>'"]/g, '') // Remove XSS vectors
    .replace(/[;\\]/g, '')   // Remove SQL delimiters
    .trim()
    .substring(0, 200)       // Length limit
}

// Strict UUID validation
export function sanitizeUUID(input: string): string {
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
  if (!uuidRegex.test(input)) throw new BadRequestError('Invalid UUID format')
  return input
}
